#include <stdio.h>

int main(void) {
    double valor;
    int centavos, n100, n50, n20, n10, n5, n2, m100, m50, m25, m10, m5, m1;
    scanf("%lf", &valor);
    centavos = (int)(valor * 100.0 + 0.5);
    n100 = centavos / 10000; centavos %= 10000;
    n50 = centavos / 5000; centavos %= 5000;
    n20 = centavos / 2000; centavos %= 2000;
    n10 = centavos / 1000; centavos %= 1000;
    n5 = centavos / 500; centavos %= 500;
    n2 = centavos / 200; centavos %= 200;
    m100 = centavos / 100; centavos %= 100;
    m50 = centavos / 50; centavos %= 50;
    m25 = centavos / 25; centavos %= 25;
    m10 = centavos / 10; centavos %= 10;
    m5 = centavos / 5; centavos %= 5;
    m1 = centavos;
    printf("NOTAS:\n");
    printf("%d nota(s) de R$ 100.00\n", n100);
    printf("%d nota(s) de R$ 50.00\n", n50);
    printf("%d nota(s) de R$ 20.00\n", n20);
    printf("%d nota(s) de R$ 10.00\n", n10);
    printf("%d nota(s) de R$ 5.00\n", n5);
    printf("%d nota(s) de R$ 2.00\n", n2);
    printf("MOEDAS:\n");
    printf("%d moeda(s) de R$ 1.00\n", m100);
    printf("%d moeda(s) de R$ 0.50\n", m50);
    printf("%d moeda(s) de R$ 0.25\n", m25);
    printf("%d moeda(s) de R$ 0.10\n", m10);
    printf("%d moeda(s) de R$ 0.05\n", m5);
    printf("%d moeda(s) de R$ 0.01\n", m1);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int a, b, c, maior_ab, maior;
    scanf("%d %d %d", &a, &b, &c);
    maior_ab = (a + b + abs(a - b)) / 2;
    maior = (maior_ab + c + abs(maior_ab - c)) / 2;
    printf("%d eh o maior\n", maior);
    return 0;
}

#include <stdio.h>

int main(void) {
    int d1, h1, m1, s1, d2, h2, m2, s2;
    int inicio, fim, duracao, dias, horas, minutos, segundos;
    scanf("Dia %d", &d1);
    scanf("%d : %d : %d", &h1, &m1, &s1);
    scanf(" Dia %d", &d2);
    scanf("%d : %d : %d", &h2, &m2, &s2);
    inicio = d1 * 86400 + h1 * 3600 + m1 * 60 + s1;
    fim = d2 * 86400 + h2 * 3600 + m2 * 60 + s2;
    duracao = fim - inicio;
    dias = duracao / 86400;
    duracao %= 86400;
    horas = duracao / 3600;
    duracao %= 3600;
    minutos = duracao / 60;
    segundos = duracao % 60;
    printf("%d dia(s)\n%d hora(s)\n%d minuto(s)\n%d segundo(s)\n", dias, horas, minutos, segundos);
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    int n;
    double r5, fib;
    scanf("%d", &n);
    r5 = sqrt(5.0);
    fib = (pow((1.0 + r5) / 2.0, n) - pow((1.0 - r5) / 2.0, n)) / r5;
    printf("%.1f\n", fib);
    return 0;
}

#include <stdio.h>

int main(void) {
    long long int a, b, soma;
    scanf("%lld %lld", &a, &b);
    soma = (a + b) * (b - a + 1) / 2;
    printf("%lld\n", soma);
    return 0;
}

